using System.IO;using System.IO.Compression;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;using System.Diagnostics;using SuperDock.Search;
class Test{
static void Pump(Func<bool> done){var frame=new DispatcherFrame();var watch=Stopwatch.StartNew();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(10)};timer.Tick+=(_,_)=>{if(done()||watch.ElapsedMilliseconds>10000)frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);timer.Stop();if(!done())throw new Exception("timeout");}
static IEnumerable<T> Children<T>(DependencyObject d)where T:DependencyObject{foreach(var child in System.Windows.LogicalTreeHelper.GetChildren(d)){if(child is T t)yield return t;if(child is DependencyObject obj)foreach(var inner in Children<T>(obj))yield return inner;}}
[STAThread]static void Main(){SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());var app=new SuperDock.App();app.InitializeComponent();app.ShutdownMode=ShutdownMode.OnExplicitShutdown;var directory=Path.Combine(AppContext.BaseDirectory,"fixtures");Directory.CreateDirectory(directory);File.WriteAllText(Path.Combine(directory,"a.txt"),"中文 TXT 内容");File.WriteAllText(Path.Combine(directory,"b.html"),"<html><body>中文 HTML 内容</body></html>");
foreach(var pair in new[]{("c.docx","word/document.xml","<root><p><t>Word内容</t></p></root>"),("d.pptx","ppt/slides/slide1.xml","<root><p><t>PPT内容</t></p></root>"),("e.xlsx","xl/worksheets/sheet1.xml","<worksheet><row><c t='inlineStr'><is><t>Excel内容</t></is></c><c><v>12345</v></c></row></worksheet>")}){var file=Path.Combine(directory,pair.Item1);if(File.Exists(file))File.Delete(file);using var zip=ZipFile.Open(file,ZipArchiveMode.Create);using var writer=new StreamWriter(zip.CreateEntry(pair.Item2).Open());writer.Write(pair.Item3);}
var type=typeof(SuperDock.App).Assembly.GetType("SuperDock.SearchViews.DocumentPreview")!;var preview=(DockPanel)Activator.CreateInstance(type,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{(Action<bool>)(_=>{}),null},null)!;var body=(ContentControl)type.GetField("body",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(preview)!;var select=type.GetMethod("Select")!;Children<Button>(preview).Single(b=>Equals(b.ToolTip,"文本预览")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
foreach(var filename in new[]{"a.txt","b.html","c.docx","d.pptx","e.xlsx","a.txt"}){select.Invoke(preview,new object[]{Path.Combine(directory,filename)});Pump(()=>body.Content is TextBox box&&!string.IsNullOrWhiteSpace(box.Text));var text=((TextBox)body.Content).Text;if(!text.Contains(filename.EndsWith("txt")?"TXT":filename.EndsWith("html")?"HTML":filename.EndsWith("docx")?"Word":filename.EndsWith("pptx")?"PPT":"12345"))throw new Exception("wrong content "+filename);Console.WriteLine("PASS text preview "+filename);}
Console.WriteLine("PASS text mode works without model binding and refreshes selection.");app.Shutdown();}
}
